function validate([n, threshold, queries]) {
  if (n < 2 || n > 10000) return 'n is between 2 and 10^4.';
  if (threshold < 0 || threshold > n) return 'threshold is between 0 and n.';
  if (queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 pairs.';
  for (const query of queries) {
    if (query.length !== 2) return 'Each query is a pair [a, b].';
    const [a, b] = query;
    if (a < 1 || a > n || b < 1 || b > n) return 'Every city in a query is between 1 and n.';
    if (a === b) return 'The two cities of a query must be different.';
  }
  return null;
}

