function areConnected(n, threshold, queries) {
  const parent = Array.from({ length: n + 1 }, (_, city) => city);
  const find = city => {
    while (parent[city] !== city) {
      parent[city] = parent[parent[city]];
      city = parent[city];
    }
    return city;
  };
  for (let z = threshold + 1; z <= n; z++) {
    for (let multiple = 2 * z; multiple <= n; multiple += z) {
      const rootZ = find(z);
      const rootMultiple = find(multiple);
      if (rootZ !== rootMultiple) {
        parent[rootMultiple] = rootZ;
      }
    }
  }
  return queries.map(([a, b]) => find(a) === find(b));
}

