function areConnected(n, threshold, queries) {
  // Search outward from a: each divisor d > threshold of a reached city opens roads to every multiple of d.
  return queries.map(([a, b]) => {
    const seen = new Set([a]);
    const opened = new Set();
    const stack = [a];
    while (stack.length) {
      const city = stack.pop();
      for (let small = 1; small * small <= city; small++) {
        if (city % small !== 0) continue;
        for (const d of [small, city / small]) {
          if (d <= threshold || opened.has(d)) continue;
          opened.add(d);
          for (let other = d; other <= n; other += d) {
            if (!seen.has(other)) {
              seen.add(other);
              stack.push(other);
            }
          }
        }
      }
    }
    return seen.has(b);
  });
}

