function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 9000 + pick(1001) : 2 + pick(29);
  const r = rand();
  // Low thresholds join most cities, high ones leave most alone; mix both.
  const threshold = r < 0.15 ? 0 : r < 0.6 ? pick(Math.max(1, Math.floor(n / 6))) : pick(n + 1);
  const count = size === 'large' ? 2000 : 1 + pick(8);
  const queries = [];
  while (queries.length < count) {
    let a = 1 + pick(n);
    let b = 1 + pick(n);
    // Half of the pairs share a divisor above threshold, so true answers appear even for high thresholds.
    const low = threshold + 1;
    const high = Math.floor(n / 2);
    if (rand() < 0.5 && low <= high) {
      const z = low + pick(high - low + 1);
      const most = Math.floor(n / z);
      a = z * (1 + pick(most));
      b = z * (1 + pick(most));
    }
    if (a !== b) queries.push([a, b]);
  }
  return [n, threshold, queries];
}
